import numpy as np

def kernel(a, b):
    M, K = a.shape
    K2, N = b.shape
    assert K == K2, "Incompatible dimensions for matrix multiplication"
    result = np.zeros((M, N), dtype=np.float32)
    tile_size_a = 128
    tile_size_b = 512

    for i in range(0, M, tile_size_a):
        for j in range(0, N, tile_size_b):
            for k in range(0, K, tile_size_a):
                # Determine the actual tile sizes to avoid out-of-bounds
                i_end = min(i + tile_size_a, M)
                k_end = min(k + tile_size_a, K)
                j_end = min(j + tile_size_b, N)
                for ii in range(i, i_end):
                    for jj in range(j, j_end):
                        for kk in range(k, k_end):
                            result[ii, jj] += a[ii, kk] * b[kk, jj]
    return result
